"""Builds index.html from the series template (videos/mcd-part2/index.html), common-props.js and scenes.js.
Run from videos/ai-explainer-see: python3 build.py"""
import re
tpl = open('../mcd-part2/index.html', encoding='utf-8').read()
head, tail = tpl[:tpl.index('// ---------- extra props ----------')], tpl[tpl.index('function renderFrame(t)'):]
head = head[:head.index('// ---------- timing')] + head[head.index('// ---------- text ----------'):]
a = head.index('// «Маркетинговые кейсы»'); b = head.index('// ------------------------------------------------------------------------------------------\nconst W')
props = open('common-props.js', encoding='utf-8').read()
for d, title, note in (('.', 'AI Explainer Reel', 'Что такое искусственный интеллект и кто его создал — просто'),):
    scenes = open(f'{d}/scenes.js', encoding='utf-8').read()
    h = head[:a] + f"// «{note}». Generated by videos/ai-explainer-see/build.py — edit scenes.js or common-props.js.\n// SEE Group brand look: paper + institutional green + gold (Unbounded headlines); scenes alternate light and dark-green panels. Deterministic: renderFrame(t).\n" + head[b:]
    h = h.replace('<title>Monopoly Case Reel 2</title>', f'<title>{title}</title>')
    h = re.sub(r"ctx\.fillText\('МАРКЕТИНГОВЫЕ КЕЙСЫ · ЧАСТЬ 2', 70, 190\);", "ctx.fillText(LABEL, 70, 190);", h)
    tail2 = tail.replace("document.fonts.load(font(800, 60), 'АБВ')", "document.fonts.load(font(800, 60), 'АБВ'), document.fonts.load('900 60px \"Playfair Display\"', 'KERIM')")
    assert tail2 != tail
    # theme colours are reassigned per scene (light paper / dark green), so they become `let`
    h, n = re.subn(r"const BG = '#[0-9a-f]+', BG2 = '#[0-9a-f]+', YEL = '#[0-9a-f]+', RED = '#[0-9a-f]+', WHITE = '#[0-9a-f]+', GREY = '#[0-9a-f]+', GREEN = '#[0-9a-f]+';",
                  "let BG = '#F7F5F0', BG2 = '#e7e2d6', YEL = '#A37E2D', RED = '#A20404', WHITE = '#104434', GREY = '#545454', GREEN = '#1f8a5b';", h); assert n == 1
    # headlines in Unbounded: font() switches family while HEADF is on; the template title() becomes titleBase()
    old = "const font = (w, s) => `${w} ${Math.round(s)}px ${F}`;"; assert old in h
    h = h.replace(old, "let HEADF = false;\nconst font = (w, s) => `${HEADF ? 800 : w} ${Math.round(s)}px ${HEADF ? 'Unbounded, ' : ''}${F}`;")
    assert 'function title(lines' in h; h = h.replace('function title(lines', 'function titleBase(lines')
    old = "ctx.fillStyle = 'rgba(255,255,255,.12)'; ctx.fillRect(70, 212"; assert old in h; h = h.replace(old, "ctx.fillStyle = EDGE; ctx.fillRect(70, 212")
    tail2 = tail2.replace("'KERIM')", "'SEE'), document.fonts.load('800 60px Unbounded', 'АБВ ABC 19'), logoImg.decode().catch(() => {})").replace('window.renderFrame = renderFrame;', 'window.renderFrame = renderFrameCam;')
    assert 'renderFrameCam;' in tail2 and 'logoImg.decode' in tail2
    open(f'{d}/index.html', 'w', encoding='utf-8').write(h + props + '\n' + scenes + '\n' + tail2)
    print(d, 'ok')
